// =====================================================================
// WF1 - Validación y sanitización de la solicitud de ticket
// Seguridad:
//  - Lista blanca: solo se aceptan los campos definidos en REGLAS;
//    cualquier otro campo enviado se ignora.
//  - Se eliminan etiquetas HTML/script y caracteres de control.
//  - Se validan longitudes mínimas y máximas y el formato del correo.
// =====================================================================
const REGLAS = {
  solicitante_nombre: { min: 3,  max: 100 },
  solicitante_correo: { min: 6,  max: 150 },
  departamento:       { min: 2,  max: 100 },
  asunto:             { min: 5,  max: 150 },
  descripcion:        { min: 10, max: 2000 },
};
const CORREO = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i;

function limpiar(valor) {
  return valor
    .replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi, '') // quita bloques <script>/<style> completos
    .replace(/<[^>]*>/g, '')                 // quita cualquier otra etiqueta HTML
    .replace(/[\u0000-\u001F\u007F]/g, ' ')  // quita caracteres de control
    .replace(/\s+/g, ' ')                    // colapsa espacios repetidos
    .trim();
}

const entrada = $input.first().json;
const headers = entrada.headers || {};
const body = entrada.body;
const origen_ip = headers['x-forwarded-for'] || headers['x-real-ip'] || 'local';

const errores = [];
const datos = {};
const esObjeto = body !== null && typeof body === 'object' && !Array.isArray(body);

if (!esObjeto) {
  errores.push('El cuerpo de la solicitud debe ser un objeto JSON');
} else {
  for (const [campo, regla] of Object.entries(REGLAS)) {
    const valor = body[campo];
    if (valor === undefined || valor === null || valor === '') {
      errores.push(`Falta el campo ${campo}`);
      continue;
    }
    if (typeof valor !== 'string') {
      errores.push(`El campo ${campo} debe ser texto`);
      continue;
    }
    const limpio = limpiar(valor);
    if (limpio.length < regla.min) {
      errores.push(`${campo} debe tener al menos ${regla.min} caracteres`);
    } else if (limpio.length > regla.max) {
      errores.push(`${campo} no puede superar ${regla.max} caracteres`);
    } else {
      datos[campo] = limpio;
    }
  }

  if (datos.solicitante_correo) {
    datos.solicitante_correo = datos.solicitante_correo.toLowerCase();
    if (!CORREO.test(datos.solicitante_correo)) {
      errores.push('solicitante_correo no tiene un formato válido');
      delete datos.solicitante_correo;
    }
  }
}

return [{
  json: {
    valido: errores.length === 0,
    errores,
    datos,
    origen_ip,
    campos_recibidos: esObjeto ? Object.keys(body).slice(0, 20) : [],
  },
}];

